import { useState, KeyboardEvent } from 'react';
import { JxInput, JxTag, JxStack, JxIconButton } from '@jinx-ui/react';

interface TagInputProps {
  onChange?: (tags: string[]) => void;
}

export default function TagInput({ onChange }: TagInputProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const commitTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const value = inputValue.trim();
    if (!value) return;
    if (!tags.includes(value)) {
      commitTags([...tags, value]);
    }
    setInputValue('');
  };

  const removeTag = (tagToRemove: string) => {
    commitTags(tags.filter((tag) => tag !== tagToRemove));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      commitTags(tags.slice(0, -1));
    }
  };

  return (
    <JxStack direction="column" gap="var(--jx-space-2)">
      <JxInput
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={addTag}
        placeholder="Введите тег и нажмите Enter"
        aria-label="Добавить тег статьи"
      />
      {tags.length > 0 && (
        <JxStack direction="row" gap="var(--jx-space-1)" wrap="wrap">
          {tags.map((tag) => (
            <JxTag key={tag} variant="removable">
              {tag}
              <JxIconButton
                icon="close"
                size="sm"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => removeTag(tag)}
              />
            </JxTag>
          ))}
        </JxStack>
      )}
    </JxStack>
  );
}

